22	// ggZZcapture: called from within the coefficient-computing routines;
23	// captures m^0, m^2 and m^4 parts of the coefficient and stores
24	// in the ggZZ_mod::res array.
25	void ggZZcapture(const std::string& label, int h34, int h56,
26	                  int j1, int j2, int j3, int j4, int j5, int j6,
27	                  std::complex<double>& amp0, std::complex<double>& amp2,
28	                  std::complex<double>& amp4) {
29	
30	    const int imt0 = 1, imt2 = 2, imt4 = 3;
31	    const int ipp  = 1, imp  = 2;
32	
33	    // Equivalent of Fortran trim(): remove trailing whitespace
34	    auto trim_str = [](const std::string& s) -> std::string {
35	        std::size_t end = s.find_last_not_of(" \t\n\r\f\v");
36	        return (end == std::string::npos) ? "" : s.substr(0, end + 1);
37	    };
38	    std::string tlabel = trim_str(label);
39	
40	    if (first) {
41	        std::fill(res.data, res.data + res.ni * res.nj * res.nk * res.nl, czip);
42	        first = false;
43	    }
44	
45	    int htag = -1;
46	    int ltag = -1, itag = -1;
47	
48	    // Canonical permutation: 1 2 3 4 5 6
49	    if ((j1 == 1) && (j2 == 2) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
50	        if ((tlabel == "1x2") && (h34 == 1) && (h56 == 1)) {
51	            htag = imp; ltag = 3; itag = c1_2;
52	        }
53	        if ((tlabel == "1x2pp") && (h34 == 1) && (h56 == 1)) {
54	            htag = ipp; ltag = 3; itag = c1_2;
55	        }
56	        if ((tlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
57	            htag = imp; ltag = 3; itag = c1_34;
58	        }
59	        if ((tlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
60	            htag = ipp; ltag = 3; itag = c1_34;
61	        }
62	        if ((tlabel == "12x34") && (h34 == 1) && (h56 == 1)) {
63	            htag = imp; ltag = 3; itag = c12_34;
64	        }
65	        if ((tlabel == "12x34pp") && (h34 == 1) && (h56 == 1)) {
66	            htag = ipp; ltag = 3; itag = c12_34;
67	        }
68	        if ((tlabel == "1x34x2mp") && (h34 == 1) && (h56 == 1)) {
69	            htag = imp; ltag = 4; itag = d1_34_2;
70	        }
71	        if ((tlabel == "1x34x2pp") && (h34 == 1) && (h56 == 1)) {
72	            htag = ipp; ltag = 4; itag = d1_34_2;
73	        }
74	        if ((tlabel == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
75	            htag = ipp; ltag = 4; itag = d2_1_34;
76	        }
77	        if ((tlabel == "2x1x34") && (h34 == 1) && (h56 == 1)) {
78	            htag = imp; ltag = 4; itag = d2_1_34;
79	        }
80	        if ((tlabel == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
81	            htag = imp; ltag = 4; itag = d6_2_1_34;
82	        }
83	        // bubble labels: first 5 chars are "bubmp" or "bubpp"; 6th char is digit
84	        if ((label.size() >= 6) && (label.substr(0, 5) == "bubmp") && (h34 == 1) && (h56 == 1)) {
85	            htag = imp; ltag = 2; itag = static_cast<int>(label[5] - '0');
86	        }
87	        if ((label.size() >= 6) && (label.substr(0, 5) == "bubpp") && (h34 == 1) && (h56 == 1)) {
88	            htag = ipp; ltag = 2; itag = static_cast<int>(label[5] - '0');
89	        }
90	    }
91	
92	    // Permute 1 and 2: 2 1 3 4 5 6
93	    if ((j1 == 2) && (j2 == 1) && (j3 == 3) && (j4 == 4) && (j5 == 5) && (j6 == 6)) {
94	        if ((tlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
95	            htag = imp; ltag = 3; itag = c2_34;
96	            if (amp0 != czip) amp0 = std::conj(amp0);
97	            if (amp2 != czip) amp2 = std::conj(amp2);
98	            if (amp4 != czip) amp4 = std::conj(amp4);
99	        }
100	        if ((tlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
101	            htag = ipp; ltag = 3; itag = c2_34;
102	            if (amp0 != czip) amp0 = std::conj(amp0);
103	            if (amp2 != czip) amp2 = std::conj(amp2);
104	            if (amp4 != czip) amp4 = std::conj(amp4);
105	        }
106	        if ((tlabel == "2x1x34") && (h34 == 1) && (h56 == 1)) {
107	            htag = imp; ltag = 4; itag = d1_2_34;
108	            if (amp0 != czip) amp0 = std::conj(amp0);
109	            if (amp2 != czip) amp2 = std::conj(amp2);
110	            if (amp4 != czip) amp4 = std::conj(amp4);
111	        }
112	        if ((tlabel == "d62x1x34") && (h34 == 1) && (h56 == 1)) {
113	            htag = imp; ltag = 4; itag = d6_1_2_34;
114	            if (amp0 != czip) amp0 = std::conj(amp0);
115	            if (amp2 != czip) amp2 = std::conj(amp2);
116	            if (amp4 != czip) amp4 = std::conj(amp4);
117	        }
118	    }
119	
120	    // Permute 3,4 and 5,6: 1 2 5 6 3 4
121	    if ((j1 == 1) && (j2 == 2) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
122	        if ((tlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
123	            htag = imp; ltag = 3; itag = c1_56;
124	        }
125	        if ((tlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
126	            htag = ipp; ltag = 3; itag = c1_56;
127	        }
128	        if ((tlabel == "2x1x34pp") && (h34 == 1) && (h56 == 1)) {
129	            htag = ipp; ltag = 4; itag = d1_2_34;
130	        }
131	    }
132	
133	    // Permute 1,3,4 and 2,5,6: 2 1 5 6 3 4
134	    if ((j1 == 2) && (j2 == 1) && (j3 == 5) && (j4 == 6) && (j5 == 3) && (j6 == 4)) {
135	        if ((tlabel == "1x34") && (h34 == 1) && (h56 == 1)) {
136	            htag = imp; ltag = 3; itag = c2_56;
137	            if (amp0 != czip) amp0 = std::conj(amp0);
138	            if (amp2 != czip) amp2 = std::conj(amp2);
139	            if (amp4 != czip) amp4 = std::conj(amp4);
140	        }
141	        if ((tlabel == "1x34pp") && (h34 == 1) && (h56 == 1)) {
142	            htag = ipp; ltag = 3; itag = c2_56;
143	            if (amp0 != czip) amp0 = std::conj(amp0);
144	            if (amp2 != czip) amp2 = std::conj(amp2);
145	            if (amp4 != czip) amp4 = std::conj(amp4);
146	        }
147	    }
148	
149	    if (htag < 0) {
150	        return;
151	    }
152	
153	    // Assign results to res array // @coverage-probe
154	    res(htag, ltag, itag, imt0) = amp0;
155	    res(htag, ltag, itag, imt2) = amp2;
156	    res(htag, ltag, itag, imt4) = amp4;
157	
158	    if (std::abs(res(htag, ltag, itag, imt0)) < 1e-8)
159	        res(htag, ltag, itag, imt0) = czip;
160	    if (std::abs(res(htag, ltag, itag, imt2)) < 1e-8)
161	        res(htag, ltag, itag, imt2) = czip;
162	    if (std::abs(res(htag, ltag, itag, imt4)) < 1e-8)
163	        res(htag, ltag, itag, imt4) = czip;
164	
165	    return;
166	}
